import 'package:flutter/material.dart'; import '../services/audio_download_service.dart'; import '../services/audio_quran_service.dart'; import '../services/quran_service.dart';
class AudioDownloadsPage extends StatefulWidget{const AudioDownloadsPage({super.key});@override State<AudioDownloadsPage> createState()=>_AudioDownloadsPageState();}
class _AudioDownloadsPageState extends State<AudioDownloadsPage>{final audio=AudioQuranService();late final AudioDownloadService downloadService;List<SurahIndex> index=[];List<DownloadedSurah> downloads=[];int? selected;bool loading=true,busy=false;int completed=0,total=0;@override void initState(){super.initState();downloadService=AudioDownloadService(audio);load();}@override void dispose(){audio.dispose();super.dispose();}Future<void> load()async{final i=await QuranService.loadQuranIndex();final d=await AudioDownloadService.loadDownloads();if(!mounted)return;setState((){index=i;downloads=d;selected=i.isNotEmpty?i.first.number:null;loading=false;});}Future<void> download()async{if(selected==null)return;setState((){busy=true;completed=0;total=0;});try{final s=await QuranService.loadSurah(selected!);await downloadService.downloadSurah(surah:s,onProgress:(a,b){if(mounted)setState((){completed=a;total=b;});});await load();}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext context){if(loading)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[const Text('تحميل السور للاستماع بدون إنترنت',style:TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:12),DropdownButtonFormField<int>(value:selected,decoration:const InputDecoration(labelText:'اختر السورة',border:OutlineInputBorder()),items:index.map((s)=>DropdownMenuItem(value:s.number,child:Text('${s.number}. ${s.name}'))).toList(),onChanged:busy?null:(v)=>setState(()=>selected=v)),if(busy)...[const SizedBox(height:12),LinearProgressIndicator(value:total==0?null:completed/total),Text('$completed من $total')],const SizedBox(height:12),FilledButton.icon(onPressed:busy?null:download,icon:const Icon(Icons.download),label:const Text('تحميل'))]))),const SizedBox(height:12),...downloads.map((d)=>Card(child:ListTile(leading:const Icon(Icons.offline_pin),title:Text('سورة ${d.surahName}'),subtitle:Text('القارئ: ${d.reciterName}'))))]);}}
